<?php get_header(); ?><main id="main-content" class="site-main container section-space"><?php $featured = new WP_Query( array( 'posts_per_page' => 1, 'ignore_sticky_posts' => false ) ); if ( $featured->have_posts() ) : $featured->the_post(); ?><section class="hero"><div class="hero__content"><?php meridian_news_categories(); ?><h1><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h1><div><?php meridian_news_excerpt(); ?></div><div class="post-meta"><?php meridian_news_posted_on(); ?><span><?php meridian_news_reading_time(); ?></span></div></div><a class="hero__image" href="<?php the_permalink(); ?>" tabindex="-1" aria-hidden="true"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'meridian-news-hero' ); } else { ?><span class="image-placeholder"></span><?php } ?></a></section><?php endif; wp_reset_postdata(); ?><section class="news-section"><div class="section-heading"><p class="eyebrow"><?php esc_html_e( 'From the newsroom', 'meridian-news' ); ?></p><h2><?php esc_html_e( 'Latest news', 'meridian-news' ); ?></h2><a class="text-link" href="<?php echo esc_url( get_permalink( get_option( 'page_for_posts' ) ) ?: home_url( '/' ) ); ?>"><?php esc_html_e( 'View all stories', 'meridian-news' ); ?></a></div><?php $latest = new WP_Query( array( 'posts_per_page' => 6, 'offset' => 1, 'ignore_sticky_posts' => true ) ); if ( $latest->have_posts() ) : ?><div class="card-grid card-grid--three"><?php while ( $latest->have_posts() ) : $latest->the_post(); get_template_part( 'template-parts/content', 'card' ); endwhile; ?></div><?php else : ?><div class="empty-state"><p><?php esc_html_e( 'Publish posts to populate the newsroom.', 'meridian-news' ); ?></p></div><?php endif; wp_reset_postdata(); ?></section><?php $categories = get_categories( array( 'hide_empty' => true, 'number' => 3 ) ); foreach ( $categories as $category ) : $stories = new WP_Query( array( 'posts_per_page' => 3, 'cat' => $category->term_id, 'ignore_sticky_posts' => true ) ); if ( $stories->have_posts() ) : ?><section class="news-section category-section"><div class="section-heading"><p class="eyebrow"><?php echo esc_html( $category->name ); ?></p><h2><?php echo esc_html( $category->description ?: sprintf( __( 'Latest in %s', 'meridian-news' ), $category->name ) ); ?></h2><a class="text-link" href="<?php echo esc_url( get_category_link( $category ) ); ?>"><?php esc_html_e( 'Browse category', 'meridian-news' ); ?></a></div><div class="card-grid card-grid--three"><?php while ( $stories->have_posts() ) : $stories->the_post(); get_template_part( 'template-parts/content', 'card' ); endwhile; ?></div></section><?php endif; wp_reset_postdata(); endforeach; ?></main><?php get_footer(); ?>
